from itertools import product
from typing import Dict, List, Tuple

Matrix = List[List[complex]]


def cup(A: complex, i: int, j: int) -> complex:
    """Coefficients of the deformed singlet  omega = A|01> - A^-1|10>."""
    if (i, j) == (0, 1):
        return A
    if (i, j) == (1, 0):
        return -1 / A
    return 0.0


def tl_generator_VV(A: complex) -> Matrix:
    """The Temperley-Lieb generator e on V (x) V, V = k^2:  e_{p,r} = -c(p)c(r)."""
    idx: List[Tuple[int, int]] = list(product((0, 1), repeat=2))
    pos: Dict[Tuple[int, int], int] = {p: k for k, p in enumerate(idx)}
    e: Matrix = [[0.0] * 4 for _ in range(4)]
    for p in idx:
        for r in idx:
            e[pos[p]][pos[r]] = -cup(A, *p) * cup(A, *r)
    return e


def mat_mul(a: Matrix, b: Matrix) -> Matrix:
    n = len(a)
    return [[sum(a[i][k] * b[k][j] for k in range(n)) for j in range(n)] for i in range(n)]


def mat_pow(a: Matrix, k: int) -> Matrix:
    """Binary exponentiation: O(log k) matrix multiplications."""
    n = len(a)
    out: Matrix = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    base = [row[:] for row in a]
    while k:
        if k & 1:
            out = mat_mul(out, base)
        base = mat_mul(base, base)
        k >>= 1
    return out


def quantum_trace_of_braid(A: complex, n: int) -> complex:
    """qtr(R^n) with ribbon weight mu = diag(-A^2, -A^-2); equals delta * <n>."""
    e = tl_generator_VV(A)
    R: Matrix = [[A * (i == j) + e[i][j] / A for j in range(4)] for i in range(4)]
    Rn = mat_pow(R, n)
    mu = [-A ** 2, -A ** (-2)]
    idx = list(product((0, 1), repeat=2))
    pos = {p: k for k, p in enumerate(idx)}
    return sum(mu[p[0]] * mu[p[1]] * Rn[pos[p]][pos[p]] for p in idx)


if __name__ == "__main__":
    A = 0.83 + 0.21j
    delta = -A ** 2 - A ** (-2)
    b = 0j
    for n in range(6):
        print(f"n={n}  qtr(R^n)={quantum_trace_of_braid(A, n):.8f}  "
              f"delta*<n>={delta * (A ** n * delta + b):.8f}")
        b = A * b + A ** n / A + delta * b / A

from math import comb
from typing import List


def q_int(q: float, m: int) -> float:
    """Naive quantum integer: numerically unstable near q = 1 (0/0)."""
    return (q ** m - q ** (-m)) / (q - 1.0 / q)


def q_int_regular(q: float, m: int) -> float:
    """Stable form  [m]_q = q^{1-m} sum_{i<m} q^{2i};  valid and exact at q = 1."""
    return q ** (1 - m) * sum(q ** (2 * i) for i in range(m))


def q_binom(q: float, n: int, j: int) -> float:
    """Gaussian binomial by the q-Pascal recursion; O(n^2) with memoisation."""
    table: List[List[float]] = [[0.0] * (n + 2) for _ in range(n + 1)]
    for a in range(n + 1):
        table[a][0] = 1.0
    for a in range(1, n + 1):
        for b in range(1, a + 1):
            table[a][b] = q ** (a - b) * table[a - 1][b - 1] + table[a - 1][b]
    return table[n][j] if j <= n else 0.0


def casimir_shifted_regular(q: float, n: int) -> float:
    """Stable form of  Omega_q(n) - Omega_q(0):  q^{1-n} S_n S_{n+2} / (q+1)^2."""
    sn = sum(q ** i for i in range(n))
    sn2 = sum(q ** i for i in range(n + 2))
    return q ** (1 - n) * sn * sn2 / (q + 1) ** 2


def degeneration_report(n: int = 5) -> None:
    """Tabulate every deformed quantity against its classical limit."""
    print(f"{'q':>10} | {'max |[m]_q-m|':>14} | {'max |C_q-C|':>12} | {'Casimir err':>12}")
    for q in (1.5, 1.2, 1.05, 1.01, 1.001, 1.00001):
        e1 = max(abs(q_int_regular(q, m) - m) for m in range(n + 1))
        e2 = max(abs(q_binom(q, n, j) - comb(n, j)) for j in range(n + 1))
        e3 = max(abs(casimir_shifted_regular(q, m) - m * (m + 2) / 4) for m in range(1, n + 1))
        print(f"{q:10.5f} | {e1:14.3e} | {e2:12.3e} | {e3:12.3e}")


if __name__ == "__main__":
    degeneration_report()
